,"name":"강철톤","parentDex":95,"dex":208,"stage":1,"stone":"각성의돌"},{"family":"snubbull","parent":"snubbull","id":"granbull","edge":"snubbull/granbull","parentName":"블루","name":"그랑블루","parentDex":209,"dex":210,"stage":1,"stone":"달의돌"},{"family":"scyther","parent":"scyther","id":"scizor","edge":"scyther/scizor","parentName":"스라크","name":"핫삼","parentDex":123,"dex":212,"stage":1,"stone":"각성의돌"},{"family":"teddiursa","parent":"teddiursa","id":"ursaring","edge":"teddiursa/ursaring","parentName":"깜지곰","name":"링곰","parentDex":216,"dex":217,"stage":1,"stone":"달의돌"},{"family":"slugma","parent":"slugma","id":"magcargo","edge":"slugma/magcargo","parentName":"마그마그","name":"마그카르고","parentDex":218,"dex":219,"stage":1,"stone":"불꽃의돌"},{"family":"swinub","parent":"swinub","id":"piloswine","edge":"swinub/piloswine","parentName":"꾸꾸리","name":"메꾸리","parentDex":220,"dex":221,"stage":1,"stone":"얼음의돌"},{"family":"remoraid","parent":"remoraid","id":"octillery","edge":"remoraid/octillery","parentName":"총어","name":"대포무노","parentDex":223,"dex":224,"stage":1,"stone":"물의돌"},{"family":"houndour","parent":"houndour","id":"houndoom","edge":"houndour/houndoom","parentName":"델빌","name":"헬가","parentDex":228,"dex":229,"stage":1,"stone":"어둠의돌"},{"family":"horsea","parent":"seadra","id":"kingdra","edge":"seadra/kingdra","parentName":"시드라","name":"킹드라","parentDex":117,"dex":230,"stage":2,"stone":"물의돌"},{"family":"phanpy","parent":"phanpy","id":"donphan","edge":"phanpy/donphan","parentName":"코코리","name":"코리갑","parentDex":231,"dex":232,"stage":1,"stone":"태양의돌"},{"family":"porygon","parent":"porygon","id":"porygon2","edge":"porygon/porygon2","parentName":"폴리곤","name":"폴리곤2","parentDex":137,"dex":233,"stage":1,"stone":"천둥의돌"},{"family":"tyrogue","parent":"tyrogue","id":"hitmontop","edge":"tyrogue/hitmontop","parentName":"배루키","name":"카포에라","parentDex":236,"dex":237,"stage":1,"stone":"각성의돌"},{"family":"happiny","parent":"chansey","id":"blissey","edge":"chansey/blissey","parentName":"럭키","name":"해피너스","parentDex":113,"dex":242,"stage":2,"stone":"빛의돌"},{"family":"larvitar","parent":"larvitar","id":"pupitar","edge":"larvitar/pupitar","parentName":"애버라스","name":"데기라스","parentDex":246,"dex":247,"stage":1,"stone":"태양의돌"},{"family":"larvitar","parent":"pupitar","id":"tyranitar","edge":"pupitar/tyranitar","parentName":"데기라스","name":"마기라스","parentDex":247,"dex":248,"stage":2,"stone":"태양의돌"},{"family":"magnemite","parent":"magneton","id":"magnezone","edge":"magneton/magnezone","parentName":"레어코일","name":"자포코일","parentDex":82,"dex":462,"stage":2,"stone":"천둥의돌"},{"family":"eevee","parent":"eevee","id":"leafeon","edge":"eevee/leafeon","parentName":"이브이","name":"리피아","parentDex":133,"dex":470,"stage":1,"stone":"리프의돌"},{"family":"eevee","parent":"eevee","id":"glaceon","edge":"eevee/glaceon","parentName":"이브이","name":"글레이시아","parentDex":133,"dex":471,"stage":1,"stone":"얼음의돌"},{"family":"eevee","parent":"eevee","id":"sylveon","edge":"eevee/sylveon","parentName":"이브이","name":"님피아","parentDex":133,"dex":700,"stage":1,"stone":"빛의돌"}]]=]

M.costScript=[=[param([ValidateSet('Editor','Sync','Library')][string]$Mode='Editor',[switch]$FamilyAvatar)
$ErrorActionPreference='Stop'
$apiRoot='https://api.github.com/repos/ccucle/frame7-nav/contents/'
$familyFiles=@{Costs='rules.json';Levels='levels.json';Powder='powder.json'}
$powderCache=Join-Path $PSScriptRoot 'family-powder.json'
$levelCache=Join-Path $PSScriptRoot 'family-unlock-levels.json'
$rulesBranch='formday-family-evolution'
$cache=Join-Path $PSScriptRoot 'family-evolution.json'
$familyLink=Join-Path $PSScriptRoot 'family-evolution.enabled'
$utf8=[Text.UTF8Encoding]::new($false)
$ProgressPreference='SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12

function Test-Count($value) {
    ($value -is [int] -or $value -is [long]) -and $value -ge 1 -and $value -le 999
}
function Convert-Rules($value) {
    if ($value.schema -ne 1 -or $value.revision -isnot [int] -and $value.revision -isnot [long] -or
        $value.revision -lt 1 -or $value.revision -gt 2147483647 -or
        !(Test-Count $value.first) -or !(Test-Count $value.second) -or $value.overrides -isnot [pscustomobject]) {
        throw '진화 규칙 파일 형식을 확인해 주세요.'
    }
    $entries=@{}
    foreach ($p in $value.overrides.PSObject.Properties) {
        if ($p.Name -cnotmatch '^[a-z0-9_-]{1,48}/[a-z0-9_-]{1,48}$' -or !(Test-Count $p.Value)) {throw '잘못된 진화 경로 또는 비용입니다.'}
        $entries[$p.Name]=[int]$p.Value
    }
    [ordered]@{schema=1;revision=[int]$value.revision;first=[int]$value.first;second=[int]$value.second;overrides=$entries}
}
function Copy-Rules($rules) {Convert-Rules (ConvertFrom-Json (ConvertTo-Json $rules -Depth 5 -Compress))}
function Get-Cost($rules,$route) {
    if ($rules.overrides.ContainsKey($route.edge)) {return $rules.overrides[$route.edge]}
    if ($route.stage -eq 1) {return $rules.first}
    $rules.second
}
function Get-Changes($before,$after,$routes) {
    foreach ($r in $routes) {
        $old=Get-Cost $before $r
        $new=Get-Cost $after $r
        if ($old -ne $new -or $before.overrides.ContainsKey($r.edge) -ne $after.overrides.ContainsKey($r.edge)) {
            [pscustomobject]@{route=$r;old=$old;new=$new;custom=$after.overrides.ContainsKey($r.edge)}
        }
    }
}
function Find-Routes($routes,[string]$query) {
    $q=$query.Trim().TrimStart('#')
    if (!$q) {return $routes}
    $families=@{}
    foreach ($r in $routes) {
        if ($q -match '^\d+$') {
            if ($q.TrimStart('0') -in @([string]$r.dex,[string]$r.parentDex)) {$families[$r.family]=1}
        } elseif (($r.name,$r.parentName,$r.id,$r.parent -join ' ').IndexOf($q,[StringComparison]::OrdinalIgnoreCase) -ge 0) {$families[$r.family]=1}
    }
    $routes | Where-Object {$families.ContainsKey($_.family)}
}
function Convert-LevelRules($value) {
    if ($value.schema -ne 1 -or ($value.revision -isnot [int] -and $value.revision -isnot [long]) -or
        $value.revision -lt 1 -or $value.revision -gt 2147483647 -or $value.levels -isnot [pscustomobject]) {throw '해금 레벨 파일 형식 오류'}
    $levels=@{}
    foreach ($pair in $value.levels.PSObject.Properties) {
        if ($pair.Name -cnotmatch '^[a-z0-9_-]{1,48}$' -or !(Test-Count $pair.Value)) {throw '해금 레벨 값 오류'}
        $levels[$pair.Name]=[int]$pair.Value
    }
    [ordered]@{schema=1;revision=[int]$value.revision;levels=$levels}
}
function Convert-FamilyDoc($value,[string]$kind) {
    switch ($kind) {
        Costs {return Convert-Rules $value}
        Levels {return Convert-LevelRules $value}
        Powder {
            $n=$value.powderPerXp
            if ($value.schema -ne 1 -or ($value.revision -isnot [int] -and $value.revision -isnot [long]) -or
                $value.revision -lt 1 -or $value.revision -gt 2147483647 -or ($n -isnot [int] -and $n -isnot [long]) -or
                $n -lt 0 -or $n -gt 999) {throw '스톤파우더 보상 규칙을 확인해 주세요.'}
            return [ordered]@{schema=1;revision=[int]$value.revision;powderPerXp=[int]$n}
        }
        default {throw '알 수 없는 가족 설정입니다.'}
    }
}
function Copy-LevelRules($rules) {Convert-LevelRules (ConvertFrom-Json (ConvertTo-Json $rules -Depth 5 -Compress))}
function Get-LevelLabel($doc,$item) {
    if ($doc.levels.ContainsKey($item.id)) {return ('Lv.'+$doc.levels[$item.id]+' · 개별')}
    if ($item.level) {return ('Lv.'+$item.level+' · 기본')}
    return '지급 레벨 미지정'
}
function Get-LevelSummary {
    if (!$state.levelBase -or !$state.levelDraft) {return}
    foreach ($item in $levelItems) {
        $before=Get-LevelLabel $state.levelBase.rules $item
        $after=Get-LevelLabel $state.levelDraft $item
        if ($before -ne $after) {("$($item.name)   $before → $after")}
    }
}


function Read-Snapshot([ValidateSet('Costs','Levels','Powder')][string]$kind='Costs') {
    $rulesApi=$apiRoot+$familyFiles[$kind]
    $reply=Invoke-RestMethod -UseBasicParsing -TimeoutSec 10 -Headers @{'User-Agent'='Formday-Evolution';'Cache-Control'='no-cache'} -Uri ($rulesApi+'?ref='+$rulesBranch+'&t='+[DateTimeOffset]::UtcNow.ToUnixTimeSeconds())
    if ($reply.sha -cnotmatch '^[a-f0-9]{40}$' -or $reply.size -gt 65536 -or $reply.encoding -ne 'base64') {throw '공유 규칙을 확인할 수 없습니다.'}
    $rules=Convert-FamilyDoc (ConvertFrom-Json ($utf8.GetString([Convert]::FromBase64String($reply.content)))) $kind
    [pscustomobject]@{sha=$reply.sha;rules=$rules}
}
function Set-Cache($rules,[ValidateSet('Costs','Levels','Powder')][string]$kind='Costs') {
    if ($kind -eq 'Levels') {$cache=$levelCache} elseif ($kind -eq 'Powder') {$cache=$powderCache}
    $lock=New-Object Threading.Mutex($false,'Local\FormdayFamilyEvolutionCache')
    $held=$false
    try {
        try {$held=$lock.WaitOne(4500)} catch [Threading.AbandonedMutexException] {$held=$true}
        if (!$held) {throw '도감 동기화가 진행 중입니다.'}
        if ([IO.File]::Exists($cache)) {
            try {$existing=Convert-FamilyDoc (ConvertFrom-Json ([IO.File]::ReadAllText($cache))) $kind
                 if ($existing.revision -ge $rules.revision) {return}} catch {}
        }
        $tmp=$cache+'.'+[guid]::NewGuid().ToString('N')+'.tmp'
        try {
            [IO.File]::WriteAllText($tmp,(ConvertTo-Json $rules -Compress -Depth 5),$utf8)
            if ([IO.File]::Exists($cache)) {[IO.File]::Replace($tmp,$cache,$cache+'.previous')} else {[IO.File]::Move($tmp,$cache)}
        } finally {if ([IO.File]::Exists($tmp)) {[IO.File]::Delete($tmp)}}
    } finally {if ($held) {$lock.ReleaseMutex()};$lock.Dispose()}
}
function Publish-Rules($base,$draft,$credential,[ValidateSet('Costs','Levels','Powder')][string]$kind='Costs') {
    $relPath=$familyFiles[$kind]
    $rulesApi=$apiRoot+$relPath
    if (!(Test-ParentAccount $credential)) {
        if ($credential -is [pscredential] -and (Test-ParentAccount 'GitHubCLI')) {$credential='GitHubCLI'}
        else {throw '저장 권한을 확인할 수 없습니다. PIN 창에서 관리자 계정을 다시 연결해 주세요.'}
    }
    $doc=Convert-FamilyDoc (ConvertFrom-Json (ConvertTo-Json $draft -Depth 5 -Compress)) $kind
    $doc.revision=$base.rules.revision+1
    $body=@{message=('Update family '+$relPath);branch=$rulesBranch;sha=$base.sha
        content=[Convert]::ToBase64String($utf8.GetBytes((ConvertTo-Json $doc -Depth 5 -Compress)))}
    try {
        if ($credential -eq 'GitHubCLI') {
            $json=(ConvertTo-Json $body -Compress) | & $githubCli api --hostname github.com --method PUT ("repos/ccucle/frame7-nav/contents/"+$relPath) --input - 2>&1
            if ($LASTEXITCODE) {
                if (($json -join ' ') -match 'HTTP (409|422)') {throw 'CONFLICT'}
                throw 'GitHub 권한 확인 실패'
            }
            $result=ConvertFrom-Json ($json -join [Environment]::NewLine)
        } else {
            $headers=@{'User-Agent'='Formday-Evolution';Authorization=('Bearer '+$credential.GetNetworkCredential().Password)}
            $result=Invoke-RestMethod -Method Put -Uri $rulesApi -UseBasicParsing -Headers $headers -TimeoutSec 15 -ContentType 'application/json' -Body (ConvertTo-Json $body -Compress)
        }
    } catch {
        if ($_.Exception.Message -eq 'CONFLICT' -or ($_.Exception.Response -and [int]$_.Exception.Response.StatusCode -in @(409,422))) {throw '다른 변경이 먼저 저장됐습니다. 새로고침한 뒤 다시 편집해 주세요.'}
        throw '공유 저장을 확인하지 못했습니다. 연결과 편집 권한을 확인한 뒤 새로고침해 주세요.'
    }
    if ($result.content.sha -cnotmatch '^[a-f0-9]{40}$') {throw '저장 결과를 확인하지 못했습니다.'}
    Set-Cache $doc $kind
    [pscustomobject]@{sha=$result.content.sha;rules=$doc}
}
Add-Type -AssemblyName System.Security
$pinFile=Join-Path $PSScriptRoot 'family-editor-pin-v1.json'
$pinScope=[Security.Cryptography.DataProtectionScope]::CurrentUser
function Write-PinState($record) {
    $tmp=$pinFile+'.'+[guid]::NewGuid().ToString('N')+'.tmp'
    try {
        [IO.File]::WriteAllText($tmp,(ConvertTo-Json $record -Compress),$utf8)
        if ([IO.File]::Exists($pinFile)) {[IO.File]::Replace($tmp,$pinFile,[NullString]::Value)} else {[IO.File]::Move($tmp,$pinFile)}
    } finally {if ([IO.File]::Exists($tmp)) {[IO.File]::Delete($tmp)}}
}
function Get-PinKey([string]$pin,[byte[]]$salt) {
    $k=[Security.Cryptography.Rfc2898DeriveBytes]::new($pin,$salt,160000,[Security.Cryptography.HashAlgorithmName]::SHA256)
    try {return ,($k.GetBytes(32))} finally {$k.Dispose()}
}
function Access-ParentPin([string]$pin,[string]$registerProvider) {
    if ($pin -cnotmatch '^[0-9]{4}$') {throw '숫자 네 자리를 입력해 주세요.'}
    $guard=[Threading.Mutex]::new($false,'Local\FormdayEvolutionParentPinV1')
    $held=$false;$key=$null
    try {
        try {$held=$guard.WaitOne(5000)} catch [Threading.AbandonedMutexException] {$held=$true}
        if (!$held) {throw '다른 편집 창에서 PIN을 확인 중이에요.'}
        if ($registerProvider) {
            if ($registerProvider -notin 'browser','existing' -or [IO.File]::Exists($pinFile)) {throw 'PIN이 이미 등록됐습니다. 창을 다시 열어 주세요.'}
            $salt=New-Object byte[] 16
            $rng=[Security.Cryptography.RandomNumberGenerator]::Create()
            try {$rng.GetBytes($salt)} finally {$rng.Dispose()}
            $key=Get-PinKey $pin $salt
            $data=[Security.Cryptography.ProtectedData]::Protect($utf8.GetBytes('family-pin-v1/'+$registerProvider),$key,$pinScope)
            Write-PinState @{salt=[Convert]::ToBase64String($salt);proof=[Convert]::ToBase64String($data);tries=0;until=0}
            return $registerProvider
        }
        $disk=ConvertFrom-Json ([IO.File]::ReadAllText($pinFile))
        $now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        if ($disk.until -gt $now) {throw ('잠시 잠겼어요. 약 '+[math]::Ceiling(($disk.until-$now)/60)+'분 뒤에 다시 입력하세요.')}
        $key=Get-PinKey $pin ([Convert]::FromBase64String($disk.salt))
        try {
            $bytes=[Security.Cryptography.ProtectedData]::Unprotect([Convert]::FromBase64String($disk.proof),$key,$pinScope)
            $provider=$utf8.GetString($bytes)
        } catch {
            $disk.tries=[int]$disk.tries+1
            if ($disk.tries -ge 5) {$disk.until=$now+300;$disk.tries=0}
            Write-PinState $disk
            if ($disk.until -gt $now) {throw '5회 틀려 5분 동안 잠겼어요.'}
            throw 'PIN이 맞지 않습니다.'
        }
        if ($provider -cnotin 'family-pin-v1/browser','family-pin-v1/existing') {throw '저장된 관리자 연결을 확인할 수 없습니다.'}
        if ($disk.tries -or $disk.until) {$disk.tries=0;$disk.until=0;Write-PinState $disk}
        return $provider.Substring(14)
    } finally {if ($key) {[Array]::Clear($key,0,$key.Length)};if ($held) {$guard.ReleaseMutex()};$guard.Dispose()}
}
function Find-LoginHelper {
    $installed=Join-Path $env:ProgramFiles 'GitHub CLI\gh.exe'
    if ([IO.File]::Exists($installed)) {return $installed}
    $app=Get-Command gh.exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($app) {return $app.Source}
    $private=Join-Path $PSScriptRoot 'github-login-2.106.0\gh.exe'
    if ([IO.File]::Exists($private)) {return $private}
}
function Install-LoginHelper {
    $arch=$env:PROCESSOR_ARCHITECTURE
    if ($env:PROCESSOR_ARCHITEW6432) {$arch=$env:PROCESSOR_ARCHITEW6432}
    $packages=@{
      AMD64=@('amd64','d406f442ca0baa3d3e9c695e9cded1aa48e67dad3294b8947e5ab84f980b4844')
      ARM64=@('arm64','6099b15d88eb96b7955050e84bd002432f9572857402d7f342c87cfaeaa83082')
      x86=@('386','de42e53d711a37640120692709693d0f51c461356b3b063d8c1d72220346333f')
    }
    $selected=$packages[$arch]
    if (!$selected) {throw '이 Windows 환경에 맞는 로그인 도구를 찾지 못했습니다.'}
    $folder=Join-Path $PSScriptRoot 'github-login-2.106.0'
    [void][IO.Directory]::CreateDirectory($folder)
    $exe=Join-Path $folder 'gh.exe'
    $tmp=Join-Path $folder ([guid]::NewGuid().ToString('N'))
    $wc=[Net.WebClient]::new()
    try {
        $wc.DownloadFile(('https://github.com/cli/cli/releases/download/v2.106.0/gh_2.106.0_windows_'+$selected[0]+'.zip'),$tmp+'.zip')
        $digest=Get-FileHash -LiteralPath ($tmp+'.zip') -Algorithm SHA256
        if ($digest.Hash -ne $selected[1]) {throw '로그인 도구 파일을 확인할 수 없습니다.'}
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        $zip=[IO.Compression.ZipFile]::OpenRead($tmp+'.zip')
        try {
            $entries=@($zip.Entries | Where-Object {$_.FullName -match '(^|/)bin/gh\.exe$|^gh\.exe$'})
            if ($entries.Count -ne 1) {throw '로그인 도구 압축 파일을 확인할 수 없습니다.'}
            [IO.Compression.ZipFileExtensions]::ExtractToFile($entries[0],$tmp)
        } finally {$zip.Dispose()}
        try {[IO.File]::Move($tmp,$exe)} catch {if (![IO.File]::Exists($exe)) {throw}}
        return $exe
    } finally {$wc.Dispose();foreach ($path in @($tmp,($tmp+'.zip'))) {if ([IO.File]::Exists($path)) {[IO.File]::Delete($path)}}}
}
function Test-ParentAccount($connection) {
    try {
        if ($connection -eq 'GitHubCLI') {
            if (!$githubCli) {return $false}
            $login=& $githubCli api --hostname github.com user --jq .login 2>$null
            if ($LASTEXITCODE -ne 0 -or $login -ne 'ccucle') {return $false}
            $canWrite=& $githubCli api --hostname github.com repos/ccucle/frame7-nav --jq .permissions.push 2>$null
            return ($LASTEXITCODE -eq 0 -and $canWrite -eq 'true')
        }
        if ($connection -isnot [pscredential]) {return $false}
        $headers=@{Authorization=('Bearer '+$connection.GetNetworkCredential().Password);'User-Agent'='Formday-Evolution'}
        $user=Invoke-RestMethod -UseBasicParsing -TimeoutSec 10 -Uri 'https://api.github.com/user' -Headers $headers
        if ($user.login -ne 'ccucle') {return $false}
        $repo=Invoke-RestMethod -UseBasicParsing -TimeoutSec 10 -Uri 'https://api.github.com/repos/ccucle/frame7-nav' -Headers $headers
        return [bool]$repo.permissions.push
    } catch {return $false}
}


if ($Mode -eq 'Library') {return}
if ($Mode -eq 'Sync') {
    if (!$FamilyAvatar -and ![IO.File]::Exists($familyLink)) {exit 0}
    $failed=$false
    foreach ($kind in 'Levels','Powder','Costs') {
        $file=$familyFiles[$kind]
        try {
            $url='https://raw.githubusercontent.com/ccucle/frame7-nav/'+$rulesBranch+'/'+$file+'?t='+[DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            $result=Invoke-WebRequest -UseBasicParsing -TimeoutSec 10 -Uri $url
            if ($result.RawContentLength -gt 65536) {throw '규칙 파일이 너무 큽니다.'}
            $body=if ($result.Content -is [byte[]]) {$utf8.GetString($result.Content)} else {$result.Content}
            Set-Cache (Convert-FamilyDoc (ConvertFrom-Json $body) $kind) $kind
        } catch {
            try {$snapshot=Read-Snapshot $kind;Set-Cache $snapshot.rules $kind} catch {$failed=$true}
        }
    }
    if ($failed) {exit 1}
    exit 0
}

