$routeFile=[IO.Path]::ChangeExtension($PSCommandPath,'.json')
$allRoutes=ConvertFrom-Json ([IO.File]::ReadAllText($routeFile))
$levelItems=ConvertFrom-Json ([IO.File]::ReadAllText([IO.Path]::ChangeExtension($PSCommandPath,'.levels.json')))
$state=@{base=$null;draft=$null;auth=$null;busy=$false}
function Update-Controls {
    $edit=$null -ne $state.auth -and $null -ne $state.base
    foreach($control in @($First,$Second,$EdgeCost,$SetEdge,$ResetEdge)) {$control.IsEnabled=$edit}
    $levelsEdit=$null -ne $state.auth -and $null -ne $state.levelBase
    foreach ($v in $levelViews.Values) {foreach ($field in 'Assign','Amount','Restore') {$v[$field].IsEnabled=$levelsEdit}}
    $Powder.IsEnabled=$null -ne $state.auth -and $null -ne $state.powderBase
    $Review.IsEnabled=switch ($Tabs.SelectedItem.Tag) {'Powder' {$Powder.IsEnabled} 'Costs' {$edit} default {$levelsEdit}}
}
function Refresh-List {
    $edge=if ($Routes.SelectedItem) {$Routes.SelectedItem.Tag.edge}
    $Routes.Items.Clear()
    foreach ($r in (Find-Routes $allRoutes $Search.Text)) {
        $item=New-Object Windows.Controls.ListBoxItem
        $kind=if ($state.draft.overrides.ContainsKey($r.edge)) {'개별 지정'}else{'기본값'}
        $item.Content=('#{0:0000} {1} → {2}  ·  {3}개  [{4}]' -f [int]$r.dex,$r.parentName,$r.name,(Get-Cost $state.draft $r),$kind)
        $item.Tag=$r
        [void]$Routes.Items.Add($item)
        if ($r.edge -eq $edge) {$Routes.SelectedItem=$item}
    }
    if (!$Routes.SelectedItem -and $Routes.Items.Count) {$Routes.SelectedIndex=0}
    if (!$Routes.Items.Count) {$Choice.Text='일치하는 진화 경로가 없습니다.';$EdgeCost.Clear()}
}
function Show-Draft($doc) {
    $state.busy=$true
    $state.draft=Copy-Rules $doc
    $First.Text=[string]$doc.first;$Second.Text=[string]$doc.second
    $state.busy=$false
    Refresh-List;Update-Controls
}
function Load-Editor {
    try {
        $snap=Read-Snapshot
        if ([IO.File]::Exists($familyLink)) {Set-Cache $snap.rules}
        $state.base=$snap;Show-Draft $snap.rules
        $Status.Text="공유 규칙 $($snap.rules.revision) · 두 PC에 적용되는 설정"
    } catch {
        $state.base=$null
        $doc=Convert-Rules (ConvertFrom-Json '{"schema":1,"revision":1,"first":1,"second":2,"overrides":{}}')
        if (Test-Path -LiteralPath $cache) {try {$doc=Convert-Rules (ConvertFrom-Json ([IO.File]::ReadAllText($cache)))} catch {}}
        Show-Draft $doc;$Status.Text='공유 규칙 연결 대기 · 저장된 비용을 표시합니다.'
    }
    Load-LevelEditor
    try {
        $snapshot=Read-Snapshot Powder
        Set-Cache $snapshot.rules Powder
        $state.powderBase=$snapshot;$rate=$snapshot.rules.powderPerXp
    } catch {
        $state.powderBase=$null;$rate=5
        if ([IO.File]::Exists($powderCache)) {try {$rate=(Convert-FamilyDoc (ConvertFrom-Json ([IO.File]::ReadAllText($powderCache))) Powder).powderPerXp} catch {}}
    }
    $Powder.Text=[string]$rate
    Show-SectionStatus
    Update-Controls
}
function Confirm-Draft {
    if (($state.powderBase -and $Powder.Text -cne [string]$state.powderBase.rules.powderPerXp) -or @(Get-LevelSummary).Count) {
        return [Windows.MessageBox]::Show($window,'저장하지 않은 변경을 버릴까요?','해금도감 설정','YesNo','Question','No') -eq 'Yes'
    }
    if (!$state.draft -or !$state.base) {return $true}
    $b=$state.base.rules
    if ($b.first -eq $state.draft.first -and $b.second -eq $state.draft.second -and
        !(Get-Changes $b $state.draft $allRoutes) -and $First.Text -eq [string]$b.first -and $Second.Text -eq [string]$b.second) {return $true}
    [Windows.MessageBox]::Show($window,'저장하지 않은 변경을 버릴까요?','진화 비용','YesNo','Question','No') -eq 'Yes'
}
function Input-Count([string]$s) {if ($s -cmatch '^[1-9][0-9]{0,2}$') {return [int]$s};return 0}
$Search.Add_TextChanged({if ($state.draft) {Refresh-List}})
$Routes.Add_SelectionChanged({
    if ($Routes.SelectedItem) {$r=$Routes.SelectedItem.Tag;$Choice.Text="$($r.parentName) → $($r.name)  ·  $($r.stone)";$EdgeCost.Text=[string](Get-Cost $state.draft $r)}
})
$changeDefaults={
    if ($state.busy -or !$state.draft) {return}
    $a=Input-Count $First.Text;$b=Input-Count $Second.Text
    if ($a -and $b) {$state.draft.first=$a;$state.draft.second=$b;Refresh-List}
}
$First.Add_TextChanged($changeDefaults);$Second.Add_TextChanged($changeDefaults)
$SetEdge.Add_Click({
    if (!$Routes.SelectedItem) {return}
    $n=Input-Count $EdgeCost.Text
    if (!$n) {$Status.Text='돌 개수는 1~999 사이의 정수로 입력해 주세요.';return}
    $state.draft.overrides[$Routes.SelectedItem.Tag.edge]=$n;Refresh-List
})
$ResetEdge.Add_Click({if ($Routes.SelectedItem) {$state.draft.overrides.Remove($Routes.SelectedItem.Tag.edge);Refresh-List}})
$Reload.Add_Click({if (Confirm-Draft) {Load-Editor}})
$Admin.Add_Click({$window.Close()})
$window.Add_Closing({param($sender,$evt) if (!(Confirm-Draft)) {$evt.Cancel=$true}})

function Open-AdminGate {
    $gate=[Windows.Markup.XamlReader]::Parse(@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Title="해금도감 · 관리자 PIN" Width="366" SizeToContent="Height" ResizeMode="NoResize" WindowStartupLocation="CenterScreen" Background="#FBF9F1" Foreground="#253F37" FontFamily="Malgun Gothic" FontSize="13" UseLayoutRounding="True">
 <StackPanel><Border Background="#253F37" Padding="20,13"><StackPanel Orientation="Horizontal"><Viewbox Width="21" Height="24" Margin="0,0,10,0"><Canvas Width="16" Height="20"><Path Fill="#F4CF88" Data="M4,8 V5 L6,2 H10 L12,5 V8 H14 V18 H2 V8 Z M6,8 H10 V5 L9,4 H7 L6,5 Z M7,12 V15 H9 V12 Z"/></Canvas></Viewbox><TextBlock Text="해금도감" Foreground="#FFF6DA" FontSize="17" FontWeight="Bold"/></StackPanel></Border>
 <StackPanel Margin="20,16,20,14"><TextBlock Name="Heading" FontSize="20" FontWeight="Bold"/><TextBlock Name="Hint" TextWrapping="Wrap" Margin="0,5,0,10" Foreground="#536B59"/>
 <PasswordBox Name="Pin" AutomationProperties.Name="관리자 PIN" MaxLength="4" FontSize="22" Padding="10,5" BorderBrush="#839D89"/>
 <StackPanel Name="Repeat"><TextBlock Text="PIN 확인" Margin="0,9,0,4"/><PasswordBox Name="Again" MaxLength="4" FontSize="22" Padding="10,5" BorderBrush="#839D89"/></StackPanel>
 <CheckBox Name="Reconnect" Content="관리자 계정 다시 연결" Margin="0,9,0,0"/>
 <TextBlock Name="Message" TextWrapping="Wrap" Foreground="#864F2F" Margin="0,6,0,5"/>
 <Button Name="Accept" IsDefault="True" FontWeight="Bold" Background="#F3CB7F" BorderBrush="#BE9656" Padding="10,7"/>
 <Button Name="Family" Content="이 PC에서 가족 규칙 받기" ToolTip="연결하면 해금도감이 가족 설정을 자동으로 받습니다." Background="#EFF3E9" BorderBrush="#BECCBE" Padding="8,5" Margin="0,8,0,0"/>
 </StackPanel></StackPanel></Window>
'@)
    $registered=[IO.File]::Exists($pinFile)
    $pin=$gate.FindName('Pin');$again=$gate.FindName('Again')
    $accept=$gate.FindName('Accept');$message=$gate.FindName('Message')
    $reconnect=$gate.FindName('Reconnect');$family=$gate.FindName('Family')
    if ($registered) {
        $gate.FindName('Heading').Text='관리자 PIN'
        $gate.FindName('Hint').Text='네 자리를 입력하면 가족 설정이 열립니다.'
        $gate.FindName('Repeat').Visibility='Collapsed';$accept.Content='편집기 열기'
    } else {
        $gate.FindName('Heading').Text='관리자 PIN 등록'
        $gate.FindName('Hint').Text='재한 PC에서 사용할 숫자 네 자리를 정하세요. 처음 한 번 관리자 계정을 확인합니다.'
        $reconnect.Visibility='Collapsed';$accept.Content='계정 확인 후 PIN 등록'
    }
    if ($FamilyAvatar -or [IO.File]::Exists($familyLink)) {$family.Visibility='Collapsed'}
    $family.Add_Click({
        try {
            [IO.File]::WriteAllText($familyLink,'1');$family.Visibility='Collapsed'
            $message.Text='연결됐습니다. 창을 닫아도 이 PC에 가족 규칙이 반영됩니다.'
        } catch {$message.Text='가족 연결을 저장하지 못했습니다.'}
    })
    $credentialFile=Join-Path $PSScriptRoot 'family-editor-current-user.xml'
    $script:githubCli=Find-LoginHelper
    $flow=@{process=$null;auth=$null}
    $watch=[Windows.Threading.DispatcherTimer]::new();$watch.Interval=[TimeSpan]::FromMilliseconds(400)
    function Complete-Admission($credential,[string]$provider) {
        if (!$registered) {[void](Access-ParentPin $pin.Password $provider)}
        [IO.File]::WriteAllText($familyLink,'1')
        $flow.auth=$credential;$gate.DialogResult=$true
    }
    $watch.Add_Tick({
        if (!$flow.process -or !$flow.process.HasExited) {return}
        $watch.Stop();$code=$flow.process.ExitCode;$flow.process.Dispose();$flow.process=$null
        $pin.IsEnabled=$true;$again.IsEnabled=$true;$accept.IsEnabled=$true
        try {
            if ($code -ne 0 -or !(Test-ParentAccount 'GitHubCLI')) {throw 'ccucle 계정의 인증이 완료되지 않았습니다.'}
            Complete-Admission 'GitHubCLI' 'browser'
        } catch {$message.Text=$_.Exception.Message}
    })
    $accept.Add_Click({
        try {
            if ($pin.Password -cnotmatch '^[0-9]{4}$') {throw '숫자 네 자리를 입력해 주세요.'}
            if (!$registered -and $pin.Password -cne $again.Password) {throw '두 PIN이 일치하지 않습니다.'}
            $old=$null
            if ([IO.File]::Exists($credentialFile)) {
                try {$old=Import-Clixml -LiteralPath $credentialFile} catch {}
            }
            if ($registered) {
                try {$provider=Access-ParentPin $pin.Password ''} catch {$pin.Clear();[void]$pin.Focus();throw}
                if (!$reconnect.IsChecked) {
                    if ($provider -eq 'existing' -and $old) {Complete-Admission $old $provider}
                    else {Complete-Admission 'GitHubCLI' $provider}
                    return
                }
            } elseif ($old -and (Test-ParentAccount $old)) {Complete-Admission $old 'existing';return}
            if ($githubCli -and (Test-ParentAccount 'GitHubCLI')) {Complete-Admission 'GitHubCLI' 'browser';return}
            if (!$githubCli) {
                $gate.Cursor=[Windows.Input.Cursors]::Wait
                try {$script:githubCli=Install-LoginHelper} finally {$gate.Cursor=$null}
            }
            $flow.process=Start-Process -FilePath $githubCli -ArgumentList 'auth','login','--hostname','github.com','--web','--git-protocol','https' -WindowStyle Normal -PassThru
            $pin.IsEnabled=$false;$again.IsEnabled=$false;$accept.IsEnabled=$false
            $message.Text='열린 브라우저에서 ccucle 계정으로 승인해 주세요.';$watch.Start()
        } catch {$message.Text=$_.Exception.Message}
    })
    $gate.Add_ContentRendered({[void]$pin.Focus()})
    try {
        if ($gate.ShowDialog() -ne $true -or !$flow.auth) {return $false}
        $state.auth=$flow.auth
        return $true
    } finally {
        $watch.Stop();if ($flow.process) {$flow.process.Dispose()}
        $pin.Clear();$again.Clear()
    }
}



$titles=@{pokemon='포켓몬';pet='펫';outfit='의상'}
$levelViews=@{}
foreach ($kind in 'pokemon','pet','outfit') {
    $tab=[Windows.Markup.XamlReader]::Parse('<TabItem xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"><DockPanel><StackPanel DockPanel.Dock="Top"><TextBlock Name="Legend" TextWrapping="Wrap" Margin="0,2,0,6"/><TextBox Name="Filter" Margin="0,0,0,6" ToolTip="이름 또는 도감 번호 검색"/></StackPanel><StackPanel DockPanel.Dock="Bottom" Margin="0,8,0,2"><TextBlock Name="Selected" Margin="0,0,0,5"/><DockPanel><Button Name="Restore" DockPanel.Dock="Right" Content="기본값 복원"/><Button Name="Assign" DockPanel.Dock="Right" Content="레벨 지정"/><TextBox Name="Amount" MaxLength="3" ToolTip="해금 레벨"/></DockPanel></StackPanel><ListBox Name="Items" Background="#FFFEF9" BorderBrush="#CAD3C8" ScrollViewer.HorizontalScrollBarVisibility="Disabled"/></DockPanel></TabItem>')
    $tab.Header=$titles[$kind]+' 레벨';$tab.Tag=$kind
    $v=@{}
    foreach ($name in 'Legend','Filter','Selected','Amount','Restore','Assign','Items') {$v[$name]=$tab.FindName($name);$v[$name].Tag=$kind}
    $v.Legend.Text=if ($kind -eq 'pokemon') {"기본형·단일형 · Lv.1~20`n이름 또는 도감 번호 검색"} else {"Lv.1~999 · 카드 전용 항목은 보유만 해금됩니다.`n이름 검색"}
    $levelViews[$kind]=$v;[void]$Tabs.Items.Add($tab)
}
function Refresh-LevelList($kind) {
    if (!$state.levelDraft) {return}
    $v=$levelViews[$kind];$selected=if ($v.Items.SelectedItem) {$v.Items.SelectedItem.Tag.id}
    $v.Items.Items.Clear();$q=$v.Filter.Text.Trim().TrimStart('#')
    foreach ($entry in $levelItems) {
        if ($entry.kind -ne $kind) {continue}
        if ($q -and $entry.name.IndexOf($q,[StringComparison]::OrdinalIgnoreCase) -lt 0 -and
            $entry.id.IndexOf($q,[StringComparison]::OrdinalIgnoreCase) -lt 0 -and
            (!$entry.dex -or [string]$entry.dex -ne $q.TrimStart('0'))) {continue}
        $row=[Windows.Controls.ListBoxItem]::new();$row.Tag=$entry
        $number=if ($entry.dex) {'#{0:0000} ' -f [int]$entry.dex} else {''}
        $availability=if ($entry.cardOnly) {' · 카드 전용'} else {''}
        $row.Content=$number+$entry.name+'   '+(Get-LevelLabel $state.levelDraft $entry)+$availability
        [void]$v.Items.Items.Add($row);if ($entry.id -eq $selected) {$v.Items.SelectedItem=$row}
    }
    if ($v.Items.Items.Count -and !$v.Items.SelectedItem) {$v.Items.SelectedIndex=0}
    if ($v.Items.SelectedItem) {$v.Items.ScrollIntoView($v.Items.SelectedItem)}
    if (!$v.Items.SelectedItem) {$v.Selected.Text='검색 결과 없음';$v.Amount.Clear()}
}
function Load-LevelEditor {
    try {$snapshot=Read-Snapshot Levels;if ([IO.File]::Exists($familyLink)) {Set-Cache $snapshot.rules Levels};$state.levelBase=$snapshot;$doc=$snapshot.rules}
    catch {
        $state.levelBase=$null;$doc=@{schema=1;revision=1;levels=@{}}
        if ([IO.File]::Exists($levelCache)) {try {$doc=Convert-LevelRules (ConvertFrom-Json ([IO.File]::ReadAllText($levelCache)))} catch {}}
    }
    $state.levelDraft=Copy-LevelRules $doc
    foreach ($k in $levelViews.Keys) {Refresh-LevelList $k}
    Update-Controls
}
foreach ($view in $levelViews.Values) {
    $view.Filter.Add_TextChanged({param($sender,$eventArgs) Refresh-LevelList $sender.Tag})
    $view.Items.Add_SelectionChanged({
        param($sender,$eventArgs)
        if (!$sender.SelectedItem) {return}
        $v=$levelViews[$sender.Tag];$item=$sender.SelectedItem.Tag
        $v.Selected.Text=$item.name+' · '+(Get-LevelLabel $state.levelDraft $item)
        $v.Amount.Text=if ($state.levelDraft.levels.ContainsKey($item.id)) {[string]$state.levelDraft.levels[$item.id]} else {[string]$item.level}
    })
    $view.Restore.Add_Click({
        param($sender,$eventArgs)
        $v=$levelViews[$sender.Tag];if (!$state.auth -or !$state.levelBase -or !$v.Items.SelectedItem) {return}
        $state.levelDraft.levels.Remove($v.Items.SelectedItem.Tag.id);Refresh-LevelList $sender.Tag
    })
    $view.Assign.Add_Click({
        param($sender,$eventArgs)
        $v=$levelViews[$sender.Tag];if (!$state.auth -or !$state.levelBase -or !$v.Items.SelectedItem) {return}
        $n=Input-Count $v.Amount.Text;$max=if ($sender.Tag -eq 'pokemon') {20} else {999}
        if (!$n -or $n -gt $max) {$Status.Text="1~$max 사이의 레벨을 입력해 주세요.";return}
        $state.levelDraft.levels[$v.Items.SelectedItem.Tag.id]=$n;Refresh-LevelList $sender.Tag
    })
}
function Show-SectionStatus {
    $kind=$Tabs.SelectedItem.Tag
    $base=switch ($kind) {'Powder' {$state.powderBase} 'Costs' {$state.base} default {$state.levelBase}}
    $Status.Text=if ($base) {'가족 규칙 연결됨'} else {'오프라인 · 최근 설정 표시'}
}
foreach ($nav in @($NavPowder,$NavDefaults,$NavRoutes,$NavPokemon,$NavPets,$NavOutfits)) {
    $nav.Add_Checked({param($sender,$evt)
        $Tabs.SelectedIndex=[int]$sender.Tag
        $PageTitle.Text=[string]$sender.Content
        Update-Controls;Show-SectionStatus
    })
}
$Tabs.Add_SelectionChanged({param($sender,$evt)
    if ($evt.Source -eq $Tabs -and $Tabs.SelectedIndex -ge 0) {
        $buttons=@($NavPowder,$NavDefaults,$NavRoutes,$NavPokemon,$NavPets,$NavOutfits)
        $buttons[$Tabs.SelectedIndex].IsChecked=$true
    }
})
function Get-PowderInput {
    if ($Powder.Text -cmatch '^(0|[1-9][0-9]{0,2})$') {return [int]$Powder.Text}
}
$Powder.Add_TextChanged({
    $n=Get-PowderInput
    $Example.Text=if ($null -eq $n) {'0~999 사이의 정수를 입력하세요.'} else {"경험치 10을 얻으면 스톤파우더 $($n*10)개"}
})

$Review.Add_Click({
    if (!$state.auth) {return}
    $kind=$Tabs.SelectedItem.Tag
    $levelMode=$kind -in 'pokemon','pet','outfit'
    if ($kind -eq 'Powder') {
        if (!$state.powderBase) {return}
        $n=Get-PowderInput
        if ($null -eq $n) {$Status.Text='0~999 사이의 정수를 입력해 주세요.';return}
        $old=$state.powderBase.rules.powderPerXp
        if ($old -eq $n) {$Status.Text='스톤파우더 지급량이 그대로입니다.';return}
        $summary=@("경험치 1당 스톤파우더   $old → $n개", "각 PC가 동기화한 뒤 새로 적립하는 경험치부터 적용합니다.")
    } elseif ($levelMode) {
        if (!$state.levelBase) {return}
        $changes=@(Get-LevelSummary)
        if (!$changes.Count) {$Status.Text='변경된 해금 레벨이 없습니다.';return}
        $summary=@("해금 레벨 변경 · $($changes.Count)개")+$changes
    } else {
    if (!$state.base) {return}
    if (!(Input-Count $First.Text) -or !(Input-Count $Second.Text)) {$Status.Text='기본값은 1~999 사이의 정수여야 합니다.';return}
    $b=$state.base.rules;$d=$state.draft
    $diff=@(Get-Changes $b $d $allRoutes)
    $summary=@()
    if ($d.first -ne $b.first) {$summary+="첫 번째 진화 기본값   $($b.first) → $($d.first)개"}
    if ($d.second -ne $b.second) {$summary+="두 번째 진화 기본값   $($b.second) → $($d.second)개"}
    if (!$diff.Count -and !$summary.Count) {$Status.Text='변경된 규칙이 없습니다.';return}
    $summary+="변경 경로 $($diff.Count)개"
    foreach ($c in $diff) {
        $routeKind=if ($c.custom) {'개별 지정'}else{'기본값'}
        $summary+="$($c.route.parentName) → $($c.route.name)   $($c.old) → $($c.new)개 · $routeKind"
    }
    }
    $preview=[Windows.Markup.XamlReader]::Parse(@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Title="변경 확인" Width="440" Height="346" MinWidth="390" MinHeight="255" Background="#FBF9F1" FontFamily="Malgun Gothic" FontSize="13" WindowStartupLocation="CenterOwner"><DockPanel Margin="18">
<TextBlock DockPanel.Dock="Top" Text="두 PC에 적용할 변경" FontWeight="Bold" FontSize="19" Foreground="#253F37" Margin="0,0,0,12"/>
<StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0"><Button Content="돌아가기" IsCancel="True" IsDefault="True" Padding="12,6"/><Button Name="Apply" Content="두 PC에 적용" Padding="12,6" Margin="6,0,0,0" Background="#F5CA76" BorderBrush="#C89C51" FontWeight="Bold"/></StackPanel>
<ListBox Name="Summary" Background="#FFFEF9" BorderBrush="#CAD3C8" Padding="6" ScrollViewer.HorizontalScrollBarVisibility="Disabled"><ListBox.ItemTemplate><DataTemplate><TextBlock Text="{Binding}" TextWrapping="Wrap" Padding="2,4"/></DataTemplate></ListBox.ItemTemplate></ListBox></DockPanel></Window>
'@)
    $preview.Owner=$window;$preview.FindName('Summary').ItemsSource=$summary
    $preview.FindName('Apply').Add_Click({$preview.DialogResult=$true})
    if ($preview.ShowDialog() -ne $true) {return}
    try {
        if ($kind -eq 'Powder') {
            $draft=@{schema=1;revision=$state.powderBase.rules.revision;powderPerXp=$n}
            $state.powderBase=Publish-Rules $state.powderBase $draft $state.auth Powder
            $Status.Text="보상 저장 완료 · 경험치 1당 스톤파우더 $n개"
        } elseif ($levelMode) {
            $saved=Publish-Rules $state.levelBase $state.levelDraft $state.auth Levels
            $state.levelBase=$saved;$state.levelDraft=Copy-LevelRules $saved.rules
            foreach ($kind in $levelViews.Keys) {Refresh-LevelList $kind}
            $Status.Text="해금 레벨 저장 완료 · 규칙 $($saved.rules.revision)"
        } else {
            $saved=Publish-Rules $state.base $d $state.auth;$state.base=$saved;Show-Draft $saved.rules
            $Status.Text="진화 비용 저장 완료 · 규칙 $($saved.rules.revision)"
        }
    }
    catch {$Status.Text=$_.Exception.Message}
})
if (!(Open-AdminGate)) {return}
$window.Add_ContentRendered({$NavPowder.IsChecked=$true;Load-Editor})
try {[void]$window.ShowDialog()} finally {$state.auth=$null}

]=]
 
M.purchaseReceiptVersion=1
M.specialPrices={articuno=20000,zapdos=20000,moltres=20000,mew=30000,mewtwo=40000}
function M.requiredForGeneration(id) return M.specialPrices[id]==nil end
function M.levelRewardAllowed(id)
return not M.specialShopEnabled or M.requiredForGeneration(id)
end
function M.purchaseDecision(wallet,owns,id)
local price=M.specialPrices[id]
if not price then return nil,"unavailable"end
if owns(id) then return nil,"owned"end
if not wallet or wallet.error then return nil,"unavailable"end
if wallet.powder<price then return nil,"low"end
return price,"ready"
end
function M.attachShop(session)
function session:purchaseStatus(id)
if not M.specialPrices[id] then return nil,"unavailable"end
if self:owns(id) then return M.specialPrices[id],"owned"end
if not M.specialShopEnabled or not self.commitPurchase then return M.specialPrices[id],"update"end
local _,status=M.purchaseDecision(self.wallet,function(target)return self:owns(target) end,id)
return M.specialPrices[id],status
end
function session:purchase(id)
if not M.specialShopEnabled or not self.commitPurchase then return false,"update"end
 
return self:commitPurchase(function(wallet)
local price,reason=M.purchaseDecision(wallet,function(target)
return wallet.forms[target] or self:owns(target)
end,id)
return price and {id=id,cost=price} or nil,reason
end)
end
end

 
local function isIntegerInRange(value, minimum, maximum)
return type(value) =="number"and value >= minimum and value <= maximum
and value == math.floor(value)
end

local function isNewFamilyDocument(document, previousRevision)
return type(document) =="table"
and document.schema == 1
and isIntegerInRange(document.revision, 1, 2147483647)
and document.revision > (previousRevision or 0)
end

function M.applyCostRules(document)
if not isNewFamilyDocument(document, M.costRevision)
or type(document.overrides) ~="table"
or not isIntegerInRange(document.first, 1, 999)
or not isIntegerInRange(document.second, 1, 999) then
return false
end
for edge, cost in pairs(document.overrides) do
if type(edge) ~="string"or #edge > 98
or not edge:match("^[a-z0-9_-]+/[a-z0-9_-]+$")
or not isIntegerInRange(cost, 1, 999) then
return false
end
end
 
for target, rule in pairs(M.evolutions) do
rule.stage = rule.stage or rule.cost
local defaultCost = rule.stage == 1 and document.first or document.second
rule.cost = document.overrides[rule.parent .."/".. target] or defaultCost
end
M.costRevision = document.revision
return true
end

M.powderPerXp = 5

function M.applyPowderRules(document)
if not isNewFamilyDocument(document, M.powderRevision)
or not isIntegerInRange(document.powderPerXp, 0, 999) then
return false
end
M.powderPerXp = document.powderPerXp
M.powderRevision = document.revision
return true
end

 
M.levelKinds = {}
M.familyLevels = {}
for _, item in ipairs(M.gallery) do
if item.kind ~="pokemon"or not M.evolutions[item.id] then
M.levelKinds[item.id] = item.kind
end
end

function M.applyLevelRules(document)
if not isNewFamilyDocument(document, M.levelRevision) or type(document.levels) ~="table"then
return false
end
local levels = {}
for id, level in pairs(document.levels) do
if type(id) ~="string"or #id > 48 or not id:match("^[a-z0-9_-]+$")
or not isIntegerInRange(level, 1, 999) then
return false
end
local kind = M.levelKinds[id]
if kind then
if kind =="pokemon"and level > 20 then return false end
levels[id] = level
elseif M.evolutions[id] then
return false
end
 
end
M.familyLevels = levels
M.levelRevision = document.revision
return true
end

function M.withFamilyLevels(items)
if not next(M.familyLevels) then return items end
local result, existing = {}, {}
for _, item in ipairs(items) do
local level = M.familyLevels[item.id]
if level then
result[#result + 1] = { id = item.id, kind = item.kind, level = level, name = item.name }
else
result[#result + 1] = item
end
existing[item.id] = true
end
for id, level in pairs(M.familyLevels) do
if not existing[id] then
result[#result + 1] = { id = id, kind = M.levelKinds[id], level = level }
end
end
return result
end

 
 
function M.powderAward(xp,rate)
return xp*(rate or M.powderPerXp)
end

function M.attachWallet(session,prefix,pending)
local wallet={xp=0,powder=0,stones={},forms={},sequence=0}
session.wallet=wallet
local function nextPath()
return prefix.."wallet-"..string.format("%09d",wallet.sequence+1)..".txn"
end
local function earnedBalance(total,rate)
if total<=wallet.xp or total>900719925474099 or rate<0 or rate>999 then return nil end
local amount=M.powderAward(total-wallet.xp,rate)
if amount>9007199254740991-wallet.powder then return nil end
return wallet.powder+amount
end
local function apply(record)
local xp=tonumber(record:match("^X (%d+)\n$"))
local rate=5 
if not xp then
local total,saved=record:match("^X (%d+) (%d+)\n$")
xp,rate=tonumber(total),tonumber(saved)
end
local balance=xp and earnedBalance(xp,rate)
local crafted=record:match("^C ([a-z]+)\n$")
local form,stone,cost=record:match("^E ([a-z0-9_-]+) ([a-z]+) (%d+)\n$")
cost=tonumber(cost)
local bought,paid=record:match("^P ([a-z0-9_-]+) (%d+)\n$")
paid=tonumber(paid)
if balance then
wallet.powder=balance
wallet.xp=xp
elseif crafted and M.stoneNames[crafted] and wallet.powder>=30 then
wallet.powder=wallet.powder-30
wallet.stones[crafted]=(wallet.stones[crafted] or 0)+1
elseif form and cost and cost>0 and (wallet.stones[stone] or 0)>=cost and not wallet.forms[form] then
wallet.stones[stone]=wallet.stones[stone]-cost
wallet.forms[form]=true
elseif bought and M.specialPrices[bought] and paid and paid>0 and wallet.powder>=paid and not wallet.forms[bought] then
wallet.powder=wallet.powder-paid
wallet.forms[bought]=true
else
wallet.error="invalid receipt"
return false
end
wallet.sequence=wallet.sequence+1
return true
end
function session:readWallet()
while not wallet.error do
local file=io.open(nextPath(),"rb")
if not file then return true end
local record=file:read(128)
local extra=file:read(1)
file:close()
if not record or extra or not apply(record) then wallet.error="invalid receipt";break end
end
return false
end
local function transact(makeRecord)
for attempt=1,8 do
if not session:readWallet() then return false end
local record,reason=makeRecord()
if not record then return false,reason end
local path=nextPath()
local file=io.open(pending,"wb")
if not file then return false end
local written=file:write(record)
local closed=file:close()
if written and closed and os.rename(pending,path) then return apply(record),"committed"end
os.remove(pending)
local winner=io.open(path,"rb")
if not winner then return false end
winner:close()
end
return false
end
function session:earn(total)
if not total or total<0 or total~=math.floor(total) or total>900719925474099 then return false end
return transact(function()
local rate=M.powderPerXp
if not earnedBalance(total,rate) then return nil end
if rate==5 then return string.format("X %.0f\n",total) end
return string.format("X %.0f %d\n",total,rate)
end)
end
function session:craft(stone)
return transact(function()
if M.stoneNames[stone] and wallet.powder>=30 then return"C "..stone.."\n"end
end)
end
function session:evolve(target)
return transact(function()
local rule=M.evolutions[target]
if rule and self:owns(rule.parent) and not self:owns(target) and (wallet.stones[rule.stone] or 0)>=rule.cost then
return string.format("E %s %s %d\n",target,rule.stone,rule.cost)
end
end)
end
function session:commitPurchase(plan)
local ok,reason=transact(function()
local purchase,status=plan(wallet)
if not purchase then return nil,status end
return string.format("P %s %d\n",purchase.id,purchase.cost)
end)
return ok,reason or"write"
end
session:readWallet()
end


