M.pets.kirby={width=84,atlas="",window=[=[local petId,special,windowWidth="kirby","inhale",84
local clips={["idle"]={start=0,ms={320,190,270,210,230,60,80,60,390}},["walk-S"]={start=9,ms={208,207,208,207,208,207,208,207}},["walk-SW"]={start=17,ms={208,207,208,207,208,207,208,207}},["walk-W"]={start=25,ms={208,207,208,207,208,207,208,207}},["walk-NW"]={start=33,ms={208,207,208,207,208,207,208,207}},["walk-N"]={start=41,ms={208,207,208,207,208,207,208,207}},["walk-NE"]={start=49,ms={208,207,208,207,208,207,208,207}},["walk-E"]={start=57,ms={208,207,208,207,208,207,208,207}},["walk-SE"]={start=65,ms={208,207,208,207,208,207,208,207}},["inhale"]={start=73,ms={180,80,80,80,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,60,80,80,80,220}},["jump"]={start=103,ms={150,80,70,60,60,55,70,55,60,60,85,60,55,55,65,55,55,80,70,250}}}
