    local l,t,r,b=limits()
    local sx,sy=read(savePosition):match("^(-?%d+),(-?%d+)")
    move(math.max(l,math.min(r,tonumber(sx) or math.floor((l+r)/2))),
         math.max(t,math.min(b,tonumber(sy) or math.floor((t+b)/2))))
    clock=os.clock()
    latestLease,lastSave=os.time(),0
