            move(gx,gy)
        else
            move(x+sx/distance,y+sy/distance)
        end
        if not acting() and not hovered then
            local horizontal=math.abs(sx)>distance*0.38 and (sx>0 and 1 or -1) or 0
            local vertical=math.abs(sy)>distance*0.38 and (sy>0 and 1 or -1) or 0
