    end
    follow(sample)
    elapsed=elapsed+ms
    local durations=clips[motion].ms
    while elapsed>=durations[frame] do
        elapsed=elapsed-durations[frame]
        frame=frame+1
        if frame>#durations then
            frame=1
            if acting() then paint("idle");break end
        end
    end
    paint(motion)
    return drawn
end
