local function var(n) return tonumber(SKIN:ReplaceVariables("#"..n.."#")) or 0 end
local function bounds()
 local l,t=var("WORKAREAX"),var("WORKAREAY")
 return l,t,math.max(l,l+var("WORKAREAWIDTH")-values[3]),math.max(t,t+var("WORKAREAHEIGHT")-values[4])
end
local function move(l,t,r,b)
 x,y=math.max(l,math.min(x,r)),math.max(t,math.min(y,b))
 local px,py=math.floor(x+0.5),math.floor(y+0.5)
 if px~=lastX or py~=lastY then SKIN:Bang("!Move",px,py);lastX,lastY=px,py end
end
local function paint(walking)
 local row,bx,by,w,h,d,g,strip,cycle=unpack(values,5,13)
 local n=walking and distance%cycle or 0
 local cx,cy
 if strip>=0 then
  local f=0
  while values[14+f] and n>=values[14+f] do f=f+1 end
  cx,cy=f*w*d,strip+(dir>0 and h*d or 0)
 else
  local f=math.floor(n/4)
  cx=math.floor(row/8)*128*g+(f*32+bx)*d
  cy=(row%8)*64*g+((dir>0 and 32 or 0)+by)*d
 end
 local crop=table.concat({cx,cy,w*d,h*d},",")
 if crop~=lastCrop then
  SKIN:Bang("!SetOption","Sprite","ImageCrop",crop); SKIN:Bang("!UpdateMeter","Sprite");lastCrop=crop
 end
